mapper.select:
select  from takeout_delivery_task d
left join takeout_order o on o.order_id = d.order_id
left join sys_user u on u.user_id = d.rider_id

    and d.task_id = #{taskId}
    and d.task_no = #{taskNo}
    and d.order_id = #{orderId}
    and o.order_no = #{orderNo}
    and d.rider_id = #{riderId}
    and d.status = #{status}
    and d.merchant_name like concat('%', #{merchantName}, '%')

order by d.create_time desc, d.task_id desc

mapper.update:
update takeout_delivery_task set rider_id = #{riderId}, status = 'ASSIGNED',
    update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where task_id = #{taskId} and status = 'UNASSIGNED' and version = #{version}

update takeout_delivery_task
arrive_time = sysdate(), pickup_time = sysdate(), deliver_time = sysdate(), status = #{toStatus}, update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where task_id = #{taskId} and rider_id = #{riderId} and status = #{fromStatus} and version = #{version}
